import networkx as nx
import os
import heapq
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Minimum-cost directed Steiner broadcast with throughput-aware cost ties."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)))
    h.remove_edges_from(list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
    ])

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dsts))
    if not terminals:
        return topology

    def edge_delay(data):
        throughput = data.get("throughput")
        try:
            throughput = float(throughput)
        except (TypeError, ValueError):
            throughput = 0.0
        return 1.0 / max(throughput, 1e-12)

    def greedy_paths():
        used = set()
        result = {}
        distances = {}
        for dst in terminals:
            try:
                distances[dst] = nx.shortest_path_length(
                    h, src, dst, weight="cost"
                )
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                distances[dst] = float("inf")

        for dst in sorted(terminals, key=lambda d: (distances[d], str(d))):
            def marginal(u, v, data):
                return 0.0 if (u, v) in used else float(data["cost"])

            try:
                path = nx.dijkstra_path(h, src, dst, weight=marginal)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                path = nx.dijkstra_path(h, src, dst, weight="cost")
            result[dst] = path
            used.update(zip(path, path[1:]))
        return result

    paths = None

    # Component-scale directed Steiner MILP: one binary activation variable
    # is shared by all destination flow commodities.
    if src in h and all(dst in h for dst in terminals):
        try:
            import numpy as np
            from scipy.optimize import Bounds, LinearConstraint, milp
            from scipy.sparse import lil_matrix

            reachable = nx.descendants(h, src) | {src}
            can_reach = set()
            for dst in terminals:
                can_reach.add(dst)
                can_reach.update(nx.ancestors(h, dst))
            useful = reachable & can_reach
            edges = [
                (u, v, data) for u, v, data in h.edges(data=True)
                if u in useful and v in useful
            ]
            commodities = [
                dst for dst in terminals
                if dst in useful and nx.has_path(h, src, dst)
            ]

            if edges and commodities == terminals and len(edges) <= 1500:
                edge_count = len(edges)
                commodity_count = len(commodities)
                variable_count = edge_count * (commodity_count + 1)

                def flow_index(commodity, edge):
                    return edge_count + commodity * edge_count + edge

                objective = np.zeros(variable_count, dtype=float)
                for i, (_, _, data) in enumerate(edges):
                    objective[i] = (
                        float(data["cost"]) + 1e-9 * edge_delay(data)
                    )

                rows = []
                lower = []
                upper = []

                for k, dst in enumerate(commodities):
                    for node in useful:
                        row = {}
                        for i, (u, v, _) in enumerate(edges):
                            j = flow_index(k, i)
                            if u == node:
                                row[j] = row.get(j, 0.0) + 1.0
                            if v == node:
                                row[j] = row.get(j, 0.0) - 1.0
                        if row:
                            demand = 1.0 if node == src else (
                                -1.0 if node == dst else 0.0
                            )
                            rows.append(row)
                            lower.append(demand)
                            upper.append(demand)

                for k in range(commodity_count):
                    for i in range(edge_count):
                        rows.append({
                            flow_index(k, i): 1.0,
                            i: -1.0,
                        })
                        lower.append(-np.inf)
                        upper.append(0.0)

                matrix = lil_matrix(
                    (len(rows), variable_count), dtype=float
                )
                for r, row in enumerate(rows):
                    for column, value in row.items():
                        matrix[r, column] = value

                integrality = np.zeros(variable_count, dtype=np.int8)
                integrality[:edge_count] = 1
                lower_bounds = np.zeros(variable_count, dtype=float)
                upper_bounds = np.ones(variable_count, dtype=float)

                result = milp(
                    c=objective,
                    integrality=integrality,
                    bounds=Bounds(lower_bounds, upper_bounds),
                    constraints=LinearConstraint(
                        matrix.tocsr(),
                        np.asarray(lower, dtype=float),
                        np.asarray(upper, dtype=float),
                    ),
                    options={"time_limit": 2.0},
                )

                if result.success and result.x is not None:
                    support = nx.DiGraph()
                    for i, (u, v, _) in enumerate(edges):
                        if result.x[i] > 0.5 and any(
                            result.x[flow_index(k, i)] > 1e-7
                            for k in range(commodity_count)
                        ):
                            support.add_edge(u, v)

                    candidate_paths = {}
                    for dst in terminals:
                        try:
                            candidate_paths[dst] = nx.shortest_path(
                                support, src, dst, weight="cost"
                            )
                        except (nx.NetworkXNoPath, nx.NodeNotFound):
                            candidate_paths = {}
                            break
                    if len(candidate_paths) == len(terminals):
                        paths = candidate_paths
        except (ImportError, ValueError, TypeError, RuntimeError):
            paths = None

    if paths is None:
        paths = greedy_paths()

    for dst in terminals:
        records = [
            [u, v, G[u][v]]
            for u, v in zip(paths[dst], paths[dst][1:])
        ]
        for partition in range(topology.num_partitions):
            for record in records:
                topology.append_dst_partition_path(dst, partition, record)

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions

        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        self.paths[dst][str(partition)] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(
            os.path.join(current_dir, "profiles/throughput.csv")
        )
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = [
        (u, v)
        for u, v, data in G.edges(data=True)
        if data.get("cost") is None
    ]
    print("Unable to get costs for: ", no_cost_pairs)
    return G


def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    return BroadCastTopology(src, dsts, num_partitions)


def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    return search_algorithm(src, dsts, G, num_partitions)

